from z3 import *

s = Solver()
x = [Int(f'x_{i}') for i in range(1, 25)]

for i in range(24):
    s.add(x[i] >= 0, x[i] <= 4)

for j in range(5):
    s.add(Sum([If(x[i] == j, i + 1, 0) for i in range(24)]) == 60)

if s.check() == sat:
    m = s.model()
    print([m.evaluate(x[i]).as_long() for i in range(24)])
else:
    print("UNSAT")
